repo.grades.py:
"""Grade records."""


class Grade:
    def __init__(self, student, score):
        self.student = student
        self.score = score

    def __repr__(self):
        return "Grade(%r, %r)" % (self.student, self.score)


ROWS = [('ana', 10), ('ben', 5), ('cho', 16), ('ben', 11), ('dev', 30), ('ana', 47), ('dev', 14)]


def load_grades():
    """Yield the stored grades one at a time."""
    for student, score in ROWS:
        yield Grade(student, score)

repo.naming.py:
"""Labels for grades."""


def label_grades(names, grades):
    """Return (lookup, lines): a name -> score dict and one 'name: score' line per grade."""
    pairs = zip(names, (x.score for x in grades))
    lookup = dict(pairs)
    lines = ["%s: %s" % (name, value) for name, value in pairs]
    return lookup, lines


def name_list(names):
    """Return the names joined by commas."""
    return ", ".join(names)

