def test_line_text():
    lookup, lines = label_grades(NAMES, list(load_grades()))
    assert lines[0] == "n0: %s" % ROWS[0][1] and lines[-1] == "n%d: %s" % (len(ROWS) - 1, ROWS[-1][1])


def test_lookup_complete():
    lookup, lines = label_grades(NAMES, load_grades())
    assert lookup == {"n%d" % i: v for i, (_, v) in enumerate(ROWS)}


def test_no_names():
    assert label_grades([], load_grades()) == ({}, [])
